<script lang="ts">
  import {page} from '$app/state';import {replaceState} from '$app/navigation';import {onMount} from 'svelte';import {request} from '#lib/client/api.ts';import type {AppData} from '#lib/client/types.ts';import Icon from './Icon.svelte';
  let {data}:{data:AppData}=$props();let email=$state('');let password=$state('');let repeatedPassword=$state('');let name=$state('');let companyName=$state('');let token=$state('');let ready=$state(false);let busy=$state(false);let error=$state('');let notice=$state('');let mode=$state<'login'|'recover'|'reset'>('login');const setup=$derived(data.view==='setup');
  $effect(()=>{if(page.url.searchParams.get('profile')==='updated')notice='Ihr Profil wurde geändert. Melden Sie sich mit Ihrer neuen E-Mail-Adresse und Ihrer bestehenden Passphrase an.';if(page.url.searchParams.get('token'))token=page.url.searchParams.get('token')||'';if(!setup&&page.url.searchParams.get('recover')==='reset'&&page.url.searchParams.get('token'))mode='reset';if(!setup&&page.url.searchParams.get('error')==='INVALID_TOKEN'){mode='recover';error='Der einmalige Link ist ungültig oder abgelaufen. Fordern Sie einen neuen Link an.';}});
  onMount(()=>{ready=true;if(setup){const params=new URLSearchParams(window.location.hash.replace(/^#/,''));if(params.has('token'))token=params.get('token')||'';}});
  async function submit(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';notice='';try{if(mode==='recover'&&!setup){await request('/api/auth/request-password-reset',{email,redirectTo:window.location.origin+'/login?recover=reset'});notice='Wenn ein passender persönlicher Zugang besteht und der Mailversand verfügbar ist, erhalten Sie einen einmaligen Link.';return;}if(mode==='reset'&&!setup){if(password!==repeatedPassword)throw new Error('Die beiden Passphrasen stimmen noch nicht überein.');await request('/api/auth/reset-password',{newPassword:password,token});password='';repeatedPassword='';mode='login';notice='Ihre Passphrase wurde geändert. Melden Sie sich mit Ihrem persönlichen Zugang an.';replaceState('/login',{});return;}if(setup)await request('/api/v1/setup',{token,name,email,password,companyName});await request('/api/auth/sign-in/email',{email,password});window.location.assign('/');}catch(e){error=e instanceof Error?e.message:'Die Anfrage ist fehlgeschlagen.';}finally{busy=false;}}
</script>
<div class="auth-page"><section class="auth-art" aria-label="SCHUBERT Design Suite"><div class="brand"><div class="brand-name">SCHUBERT</div><div class="brand-sub">DESIGN SUITE</div></div><div class="auth-art-copy"><h1>Von der ersten Idee<br/>bis zum letzten Detail.</h1><p>Ein gemeinsamer Arbeitsbereich für Beratung, Planung, Büro, Werkstatt und Baustelle.</p></div><footer class="auth-art-footer"><span>SCHUBERT · DESIGN & GRABDENKMALE</span><span>PRÄZISION VERBINDET.</span></footer></section><main class="auth-form-wrap"><form class="auth-form" onsubmit={submit}><h1>{setup?'Der Rahmen für Ihren Betrieb.':mode==='recover'?'Wieder Zugang erhalten.':mode==='reset'?'Eine neue Passphrase.':'Gut vorbereitet in den Tag.'}</h1><p>{setup?'Richten Sie das erste persönliche Verwaltungskonto ein. Weitere Zugänge werden anschließend gezielt vergeben.':mode==='recover'?'Geben Sie Ihre geschäftliche E-Mail an. Der Wiederherstellungslink ist einmalig und zeitlich begrenzt.':mode==='reset'?'Wählen Sie eine lange, persönliche Passphrase für Ihren Zugang.':'Melden Sie sich mit Ihrem persönlichen Zugang an.'}</p>{#if error}<div class="notice error" role="alert"><Icon name="alert" size={18}/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name="check" size={18}/><div>{notice}</div></div>{/if}{#if !data.connected}<div class="notice warning"><Icon name="alert" size={18}/><div>Die Datenbankverbindung ist noch nicht bereit. Die Serverkonfiguration muss zuerst vervollständigt werden.</div></div>{/if}{#if setup&&data.summary?.setupAvailable===false}<div class="notice warning"><Icon name="lock" size={18}/><div>Die einmalige Einrichtung ist derzeit nicht freigeschaltet. Prüfen Sie den Betriebszustand oder melden Sie sich mit einem bestehenden Zugang an.</div></div><a class="text-link mb" href="/login">Zur Anmeldung<Icon name="arrow" size={15}/></a>{/if}{#if setup}<div class="field"><label for="setup-token">Einrichtungsschlüssel *</label><input id="setup-token" type="password" bind:value={token} autocomplete="off" required/><span class="field-help">Der einmalige Schlüssel aus der geschützten Serverkonfiguration.</span></div><div class="field"><label for="setup-company">Betriebsname *</label><input id="setup-company" bind:value={companyName} autocomplete="organization" required/></div><div class="field"><label for="setup-name">Ihr vollständiger Name *</label><input id="setup-name" bind:value={name} autocomplete="name" required/></div>{/if}{#if mode!=='reset'||setup}<div class="field"><label for="login-email">Geschäftliche E-Mail *</label><input id="login-email" type="email" bind:value={email} autocomplete="username" required/></div>{/if}{#if mode!=='recover'||setup}<div class="field"><label for="login-password">{setup||mode==='reset'?'Persönliche Passphrase':'Passwort'} *</label><input id="login-password" type="password" bind:value={password} autocomplete={setup||mode==='reset'?'new-password':'current-password'} minlength={setup||mode==='reset'?15:undefined} maxlength="128" required/>{#if setup||mode==='reset'}<span class="field-help">Mindestens 15 Zeichen. Verwenden Sie eine lange, persönliche Passphrase.</span>{/if}</div>{/if}{#if mode==='reset'&&!setup}<div class="field"><label for="repeat-password">Passphrase wiederholen *</label><input id="repeat-password" type="password" bind:value={repeatedPassword} autocomplete="new-password" minlength="15" maxlength="128" required/></div>{/if}<button class="btn primary full" type="submit" disabled={!ready||busy||!data.connected||setup&&data.summary?.setupAvailable===false}>{!ready?'Anmeldung wird vorbereitet …':busy?'Wird geprüft …':setup?'Betrieb einrichten':mode==='recover'?'Einmaligen Link anfordern':mode==='reset'?'Neue Passphrase speichern':'Sicher anmelden'}<Icon name={busy?'refresh':'arrow'} size={17} class={busy?'spin':''}/></button>{#if !setup}<button class="text-link mt" type="button" onclick={()=>{mode=mode==='login'?'recover':'login';error='';notice='';}}>{mode==='login'?'Passwort vergessen?':'Zurück zur Anmeldung'}</button>{/if}<p class="auth-legal">{setup?'Die Einrichtung ist nur einmal möglich. Firmierung, Steuerdaten und Freigaben ergänzen Sie anschließend in der Betriebsverwaltung.':'Der Zugang wird vom Betrieb freigeschaltet. Bei fehlenden Anmeldedaten wenden Sie sich an Ihre zuständige Verwaltung.'}</p></form></main></div>
